#!/usr/bin/env bash
# tools/build-assets.sh - embed src/* and lib/abi_gates.sh as base64 in lib/assets.sh.
#
# Why: the single-file guest script (gpupv-fnos.sh) must be able to
#   * write the C probe and the HTTP receiver, and
#   * run the offline ABI gates,
# on a machine that has no repo checkout - just that one file. Embedding them as
# payloads keeps ONE source of truth (src/ and lib/abi_gates.sh) while the
# generated file stays self-contained.
#
# Regenerate after any change to src/* or lib/abi_gates.sh:
#   bash tools/build-assets.sh && bash tools/build-single.sh
set -eu
cd "$(dirname "$0")/.."
OUT=lib/assets.sh
{
	echo '# shellcheck shell=bash'
	echo '# GENERATED by tools/build-assets.sh from src/* and lib/abi_gates.sh - do not edit.'
	echo '# Base64 payloads let the single-file build (gpupv-fnos.sh) materialise the'
	echo '# helper files it needs without a repo checkout.'
	echo
	printf '%s=%s\n' GPUPV_ASSET_DXG_PROBE_B64 \
		"'$(base64 -w0 src/dxg_probe.c)'"
	printf '%s=%s\n' GPUPV_ASSET_HTTP_PUT_SERVER_B64 \
		"'$(base64 -w0 src/http_put_server.py)'"
	printf '%s=%s\n' GPUPV_ASSET_LDPRELOAD_TRACE_B64 \
		"'$(base64 -w0 src/ldpreload_trace.c)'"
	printf '%s=%s\n' GPUPV_ASSET_ABI_GATES_B64 \
		"'$(base64 -w0 lib/abi_gates.sh)'"
} > "$OUT"
bash -n "$OUT" || { echo "!! $OUT has a syntax error" >&2; exit 1; }
printf 'wrote %s (%s bytes)\n' "$OUT" "$(stat -c%s "$OUT")"
